    function shouldPoll(){return s.alive&&!document.hidden&&s.info&&(s.mode==='waiting'&&q('[data-hst-auto-admission]').checked||s.mode==='connected'&&s.info.host&&!q('[data-hst-panel="people"]').hidden);}
