async function guard(work){if(s.busy){notice('Đang xử lý thao tác trước. Bạn có thể rời phòng hoặc dừng thử thiết bị bất cứ lúc nào.');return;}s.busy=true;s.node.setAttribute('aria-busy','true');controls();try{await work();}catch(e){if(s.alive)notice(e.name==='NotAllowedError'?'Bạn chưa cho phép thiết bị hoặc đã hủy chia sẻ.':e.name==='NotFoundError'?'Không tìm thấy thiết bị. Kiểm tra kết nối mic/camera và chọn lại.':e.name==='NotReadableError'?'Thiết bị đang bận hoặc không truy cập được. Đóng ứng dụng đang dùng thiết bị rồi thử lại.':e.name==='OverconstrainedError'?'Thiết bị không hỗ trợ cấu hình này. Chọn thiết bị khác hoặc giảm chất lượng.':e.name==='AbortError'?'Yêu cầu đã hủy hoặc hết thời gian chờ.':e.message,true);}finally{s.busy=false;s.node.removeAttribute('aria-busy');if(s.alive)controls();}}
