    async function devices(){if(!navigator.mediaDevices?.enumerateDevices)throw Error('Trình duyệt chưa hỗ trợ danh sách thiết bị.');const all=await navigator.mediaDevices.enumerateDevices();for(const select of s.node.querySelectorAll('[data-hst-device],[data-hst-pre-device]')){const kind=select.dataset.hstDevice||select.dataset.hstPreDevice;select.replaceChildren(new Option('Mặc định',''));all.filter(d=>d.kind===kind).forEach((d,i)=>select.add(new Option(d.label||'Thiết bị '+(i+1),d.deviceId)));select.value=s.devices[kind]||'';if(kind==='audiooutput')select.disabled=!HTMLMediaElement.prototype.setSinkId;}notice('Đã đọc danh sách thiết bị. Chưa cấp quyền có thể chưa hiện tên; chưa bật mic/camera.');}
