      if(e.hasAttribute('data-hst-queue-kind'))filterQueue();
      if(e.hasAttribute('data-hst-duration'))q('[data-hst-custom-duration-label]').hidden=e.value!=='custom'||!s.info?.host;
      if(e.hasAttribute('data-hst-preset'))applyPreset(e.value);else if(e.closest('[data-hst-create]')&&e.name!=='title'){q('[data-hst-preset]').value='custom';presetDetail();}
